package main

import (
	"go/parser"
	"go/token"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestEmitResource_Smoke(t *testing.T) {
	r := ResourceModel{
		Message: "drill.v1.User", Package: "drillv1", GoType: "*drillv1.User",
		Table: "users", PK: "id", SoftDelete: "deleted_at", EmptyMask: "ErrorOnEmpty",
		Bindings: []BindingModel{
			{Proto: "display_name", Column: "display_name", SQLType: "text", Writable: true, Codec: ""},
			{Proto: "id", Column: "id", SQLType: "uuid", Writable: false, Codec: ""},
		},
		AutoSet: []AutoSetModel{{Column: "updated_at", SQLLiteral: "NOW()"}},
	}
	out, err := emitResource(r, "github.com/btc/drill/internal/pb/drill/v1")
	require.NoError(t, err)
	require.Contains(t, out, `package patches`)
	require.Contains(t, out, `Code generated by aippatchgen. DO NOT EDIT.`)
	require.Contains(t, out, `var UserPatch = &aippatch.Mapping[*drillv1.User]{`)
	require.Contains(t, out, `Table:      "users",`)
	require.Contains(t, out, `{Proto: "display_name", Column: "display_name", SQLType: "text", Writable: true, Codec: ""},`)
	require.Contains(t, out, `{Column: "updated_at", SQLLiteral: "NOW()"},`)
	// Assert it's gofmt-clean / parse-able Go.
	require.NoError(t, parseGoFile(out))
}

func parseGoFile(src string) error {
	_, err := parser.ParseFile(token.NewFileSet(), "out.go", src, 0)
	return err
}

func TestEmitInit_Smoke(t *testing.T) {
	codecs := map[string]CodecModel{
		"enum_role": {
			Name: "enum_role", ProtoEnum: "drill.v1.UserRole",
			Values: []EnumValue{
				{Number: 1, GoConst: "UserRole_USER_ROLE_CANDIDATE", Text: "candidate"},
				{Number: 2, GoConst: "UserRole_USER_ROLE_ADMIN", Text: "admin"},
			},
		},
	}
	resources := []string{"UserPatch"}
	out, err := emitInit(codecs, resources, "drillv1", "github.com/btc/drill/internal/pb/drill/v1")
	require.NoError(t, err)
	require.Contains(t, out, "var Codecs = map[string]aippatch.EnumCodec{")
	require.Contains(t, out, `"enum_role":`)
	require.Contains(t, out, `int32(drillv1.UserRole_USER_ROLE_CANDIDATE): "candidate",`)
	require.Contains(t, out, "func InitPatches() error {")
	require.Contains(t, out, "UserPatch.Validate,")
	require.NoError(t, parseGoFile(out))
}
